//! The door's guarantee, held against korg's **real** tool catalogue
//! (`crates/korg-mcp/tests/tools_schema.json`, regenerated by `just gen`), so it
//! drifts with korg's tool surface rather than a hand-typed list — and, for the
//! klams door, against klams's catalogue as committed at `tests/klams_tools.json`.
//!
//! Both doors' rulings are total (korg's since sprint 095, klams's since 097):
//! every tool is a read, a ruled write, or refused by name, and a tool either
//! upstream adds fails here until somebody says which.

mod common;

use common::*;
use korg_gate::allowlist::{
    limited, looks_read_only, DUET_ORIGIN, KLAMS_READ_TOOLS, KLAMS_REFUSED_TOOLS,
    KLAMS_WRITE_TOOLS, READ_TOOLS, REFUSED_TOOLS, WRITE_TOOLS,
};
use serde_json::json;

fn korg_rulings() -> impl Iterator<Item = &'static &'static str> {
    READ_TOOLS.iter().chain(WRITE_TOOLS).chain(REFUSED_TOOLS)
}

#[test]
fn every_ruled_tool_exists_in_the_catalogue() {
    let catalogue = catalogue();
    for name in korg_rulings() {
        assert!(
            catalogue.iter().any(|c| c == name),
            "the korg rulings name `{name}`, which korg no longer serves — drop it"
        );
    }
}

#[test]
fn every_korg_tool_has_been_ruled_on() {
    // A new korg tool fails here until somebody decides whether it may reach
    // the public internet: READ_TOOLS, WRITE_TOOLS (a decision, korg+ GP-17)
    // or REFUSED_TOOLS.
    let unruled: Vec<_> = catalogue()
        .into_iter()
        .filter(|n| !korg_rulings().any(|r| r == n))
        .collect();
    assert!(
        unruled.is_empty(),
        "korg serves tools korg-gate has not ruled on: {unruled:?} \
         (crates/korg-gate/src/allowlist.rs)"
    );
}

#[test]
fn every_read_shaped_tool_in_the_catalogue_is_a_read() {
    // If a `get_`/`list_` tool is not a pure read, the naming is the bug.
    let misfiled: Vec<_> = catalogue()
        .into_iter()
        .filter(|n| looks_read_only(n) && !READ_TOOLS.contains(&n.as_str()))
        .collect();
    assert!(
        misfiled.is_empty(),
        "read-shaped but not in READ_TOOLS: {misfiled:?}"
    );
}

#[test]
fn the_write_set_is_exactly_the_ruled_nine() {
    assert_eq!(
        WRITE_TOOLS,
        [
            "add_comment",
            "create_link",
            "create_program",
            "create_work_item",
            "propose_sprint",
            "relate",
            "set_awaiting",
            "update_schedule",
            "update_work_item"
        ],
        "widening the korg door's writes is a decision (korg+ GP-17), not an edit"
    );
}

#[tokio::test]
async fn every_refused_tool_is_refused_on_call_and_the_list_is_reads_plus_writes() {
    let h = Harness::start().await;
    let (_, token, _) = h.access_token().await;

    assert!(
        REFUSED_TOOLS.len() > 20,
        "the catalogue lost its refused writes? {REFUSED_TOOLS:?}"
    );
    for (i, name) in REFUSED_TOOLS.iter().enumerate() {
        let resp = h
            .rpc(
                &token,
                json!({"jsonrpc":"2.0","id":i,"method":"tools/call",
                       "params":{"name":name,"arguments":{}}}),
            )
            .await;
        assert_eq!(
            resp.status(),
            200,
            "{name}: a refusal is a JSON-RPC error, not an HTTP one"
        );
        let body = resp.json_value().await;
        assert_eq!(body["id"], i, "{name}");
        assert!(
            body["error"]["code"].is_i64(),
            "{name} was not refused: {body}"
        );
        assert!(body.get("result").is_none(), "{name}");
    }
    assert!(
        h.seen
            .0
            .lock()
            .unwrap()
            .iter()
            .all(|(_, m)| m["method"] != "tools/call"),
        "a refused tools/call reached korg"
    );

    let listed = h
        .rpc(
            &token,
            json!({"jsonrpc":"2.0","id":"l","method":"tools/list"}),
        )
        .await
        .json_value()
        .await;
    let mut names: Vec<&str> = listed["result"]["tools"]
        .as_array()
        .unwrap()
        .iter()
        .map(|t| t["name"].as_str().unwrap())
        .collect();
    for name in REFUSED_TOOLS {
        assert!(!names.contains(name), "{name} is listed");
    }
    let mut expected: Vec<&str> = READ_TOOLS.iter().chain(WRITE_TOOLS).copied().collect();
    expected.sort_unstable();
    names.sort_unstable();
    assert_eq!(names, expected);
    assert_eq!(names.len(), 36); // 27 reads (list_tagged_days joined in sprint 101) + 9 writes
}

#[tokio::test]
async fn every_write_tool_reaches_korg_stamped_as_duet() {
    let h = Harness::start().await;
    let (_, token, _) = h.access_token().await;

    // Field-limited writes have their own test below; any extra argument
    // would be refused.
    let open: Vec<_> = WRITE_TOOLS
        .iter()
        .filter(|n| limited(n).is_none())
        .collect();
    for (i, name) in open.iter().enumerate() {
        let body = h
            .rpc(
                &token,
                json!({"jsonrpc":"2.0","id":i,"method":"tools/call",
                       "params":{"name":name,"arguments":{"title":"t","origin":"overseer"}}}),
            )
            .await
            .json_value()
            .await;
        assert_eq!(
            body["result"]["content"][0]["text"],
            format!("called {name}"),
            "{name}: {body}"
        );
    }
    let seen = h.seen.0.lock().unwrap();
    let calls: Vec<_> = seen
        .iter()
        .filter(|(_, m)| m["method"] == "tools/call")
        .collect();
    assert_eq!(calls.len(), open.len());
    for (headers, msg) in calls {
        let name = msg["params"]["name"].as_str().unwrap();
        assert_eq!(headers["x-homelab-agent"], "claude-duet", "{name}");
        // Everything but origin passes as sent.
        assert_eq!(msg["params"]["arguments"]["title"], "t", "{name}");
        let origin = &msg["params"]["arguments"]["origin"];
        match name {
            // The two tools with korg's `origin` field: overwritten.
            "add_comment" | "relate" => assert_eq!(origin, DUET_ORIGIN, "{name}"),
            // Anything else is not the gate's field to touch.
            _ => assert_eq!(origin, "overseer", "{name}"),
        }
    }
}

#[tokio::test]
async fn update_schedule_reaches_korg_with_a_status_and_nothing_else() {
    let h = Harness::start().await;
    let (_, token, _) = h.access_token().await;

    // The three status moves forward untouched.
    for (i, status) in ["done", "paused", "active"].iter().enumerate() {
        let body = h
            .rpc(
                &token,
                json!({"jsonrpc":"2.0","id":i,"method":"tools/call",
                       "params":{"name":"update_schedule",
                                 "arguments":{"node_id":3950,"status":status}}}),
            )
            .await
            .json_value()
            .await;
        assert_eq!(
            body["result"]["content"][0]["text"], "called update_schedule",
            "{status}: {body}"
        );
    }
    {
        let seen = h.seen.0.lock().unwrap();
        assert_eq!(seen.len(), 3);
        for ((headers, msg), status) in seen.iter().zip(["done", "paused", "active"]) {
            assert_eq!(headers["x-homelab-agent"], "claude-duet");
            assert_eq!(
                msg["params"]["arguments"],
                json!({"node_id":3950,"status":status})
            );
        }
    }

    // Anything else — another field alongside, a field without the status, no
    // target, no arguments, arguments that are not an object — is refused.
    let refused = [
        json!({"node_id":3950,"status":"done","notes":"retired"}),
        json!({"node_id":3950,"status":"done","archived":true}),
        json!({"node_id":3950,"status":"done","origin":"overseer"}),
        json!({"node_id":3950,"cadence":"yearly"}),
        json!({"node_id":3950,"anchor_at":"2027-01-01T00:00:00Z"}),
        json!({"node_id":3950}),
        json!({"status":"done"}),
        json!({}),
        json!(null),
        json!("node_id=3950 status=done"),
    ];
    for (i, arguments) in refused.iter().enumerate() {
        let body = h
            .rpc(
                &token,
                json!({"jsonrpc":"2.0","id":100 + i,"method":"tools/call",
                       "params":{"name":"update_schedule","arguments":arguments}}),
            )
            .await
            .json_value()
            .await;
        assert_eq!(body["error"]["code"], -32602, "{arguments}: {body}");
        assert!(
            body["error"]["message"]
                .as_str()
                .unwrap()
                .contains("takes exactly `node_id` and `status`"),
            "{body}"
        );
    }
    // No `arguments` key at all.
    let body = h
        .rpc(
            &token,
            json!({"jsonrpc":"2.0","id":200,"method":"tools/call",
                   "params":{"name":"update_schedule"}}),
        )
        .await
        .json_value()
        .await;
    assert_eq!(body["error"]["code"], -32602, "{body}");
    assert_eq!(
        h.seen.0.lock().unwrap().len(),
        3,
        "an off-limit update_schedule reached korg"
    );
}

#[tokio::test]
async fn the_other_schedule_writes_stay_refused() {
    // The negative control for WI 4322: opening update_schedule opened nothing
    // next to it.
    let h = Harness::start().await;
    let (_, token, _) = h.access_token().await;
    for (i, name) in ["create_schedule", "materialize_schedule"]
        .iter()
        .enumerate()
    {
        assert!(REFUSED_TOOLS.contains(name), "{name}");
        let body = h
            .rpc(
                &token,
                json!({"jsonrpc":"2.0","id":i,"method":"tools/call",
                       "params":{"name":name,"arguments":{"node_id":3950}}}),
            )
            .await
            .json_value()
            .await;
        assert_eq!(body["error"]["code"], -32602, "{name}: {body}");
    }
    assert!(h.seen.0.lock().unwrap().is_empty());
}

#[tokio::test]
async fn origin_is_stamped_when_the_caller_sends_none_and_refused_on_non_object_arguments() {
    let h = Harness::start().await;
    let (_, token, _) = h.access_token().await;

    for (i, arguments) in [json!({"node_id": 1, "body": "b"}), json!(null)]
        .into_iter()
        .enumerate()
    {
        h.rpc(
            &token,
            json!({"jsonrpc":"2.0","id":i,"method":"tools/call",
                   "params":{"name":"add_comment","arguments":arguments}}),
        )
        .await;
    }
    // No `arguments` key at all.
    h.rpc(
        &token,
        json!({"jsonrpc":"2.0","id":2,"method":"tools/call","params":{"name":"relate"}}),
    )
    .await;
    {
        let seen = h.seen.0.lock().unwrap();
        let origins: Vec<_> = seen
            .iter()
            .map(|(_, m)| m["params"]["arguments"]["origin"].clone())
            .collect();
        assert_eq!(origins, [DUET_ORIGIN, DUET_ORIGIN, DUET_ORIGIN]);
        assert_eq!(seen[0].1["params"]["arguments"]["body"], "b");
    }

    let body = h
        .rpc(
            &token,
            json!({"jsonrpc":"2.0","id":9,"method":"tools/call",
                   "params":{"name":"add_comment","arguments":"origin=overseer"}}),
        )
        .await
        .json_value()
        .await;
    assert_eq!(body["error"]["code"], -32602, "{body}");
    assert_eq!(
        h.seen.0.lock().unwrap().len(),
        3,
        "an unstampable call reached korg"
    );
}

#[tokio::test]
async fn non_lifecycle_methods_batches_and_responses_are_refused() {
    let h = Harness::start().await;
    let (_, token, _) = h.access_token().await;

    for method in [
        "resources/list",
        "resources/read",
        "prompts/list",
        "completion/complete",
        "logging/setLevel",
    ] {
        let body = h
            .rpc(&token, json!({"jsonrpc":"2.0","id":1,"method":method}))
            .await
            .json_value()
            .await;
        assert_eq!(body["error"]["code"], -32601, "{method}");
    }

    // A refused notification has no id to answer: HTTP 400.
    let resp = h
        .rpc(
            &token,
            json!({"jsonrpc":"2.0","method":"notifications/roots/list_changed"}),
        )
        .await;
    assert_eq!(resp.status(), 400);

    // A batch is refused whole, even one that hides a write behind a read.
    let resp = h
        .rpc(
            &token,
            json!([{"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"get_item"}},
                   {"jsonrpc":"2.0","id":2,"method":"tools/call","params":{"name":"delete_area"}}]),
        )
        .await;
    assert_eq!(resp.status(), 400);

    assert!(
        h.seen.0.lock().unwrap().is_empty(),
        "a refused message reached korg"
    );

    // The lifecycle still passes.
    let resp = h
        .rpc(
            &token,
            json!({"jsonrpc":"2.0","id":1,"method":"initialize","params":{}}),
        )
        .await;
    assert_eq!(resp.status(), 200);
    let resp = h
        .rpc(
            &token,
            json!({"jsonrpc":"2.0","method":"notifications/initialized"}),
        )
        .await;
    assert_eq!(resp.status(), 202);
}

#[tokio::test]
async fn duplicate_keys_cannot_smuggle_a_write_past_the_check() {
    let h = Harness::start().await;
    let (_, token, _) = h.access_token().await;
    // serde keeps the last duplicate; whatever the gate checked is what it
    // forwards, because it forwards its own re-serialisation.
    let raw = r#"{"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"delete_area","name":"get_item"}}"#;
    let resp = h
        .http
        .post(h.url("/mcp"))
        .bearer_auth(&token)
        .header("content-type", "application/json")
        .body(raw)
        .send()
        .await
        .unwrap();
    assert_eq!(resp.status(), 200);
    let seen = h.seen.0.lock().unwrap();
    let (_, forwarded) = seen.last().unwrap();
    assert_eq!(forwarded["params"]["name"], "get_item");
}

// ---- The klams door (sprint 094, WI 4293; writes sprint 097, WI 4324) ----

fn klams_rulings() -> impl Iterator<Item = &'static &'static str> {
    KLAMS_READ_TOOLS
        .iter()
        .chain(KLAMS_WRITE_TOOLS)
        .chain(KLAMS_REFUSED_TOOLS)
}

/// A UUID that is nobody's bound author: what a caller would send to write as
/// another agent.
const FOREIGN_AUTHOR: &str = "0195f000-0000-7000-8000-00000000beef";

#[test]
fn every_klams_tool_has_been_ruled_on_and_every_ruling_names_a_real_tool() {
    // klams has no read naming rule to lean on, so the ruling is total: a tool
    // klams adds fails here until it is put in KLAMS_READ_TOOLS or
    // KLAMS_WRITE_TOOLS (published to the internet) or KLAMS_REFUSED_TOOLS.
    let catalogue = klams_catalogue();
    let unruled: Vec<_> = catalogue
        .iter()
        .filter(|n| !klams_rulings().any(|r| r == n))
        .collect();
    assert!(
        unruled.is_empty(),
        "klams serves tools korg-gate has not ruled on: {unruled:?} \
         (crates/korg-gate/src/allowlist.rs)"
    );
    for name in klams_rulings() {
        assert!(
            catalogue.iter().any(|c| c == name),
            "the klams rulings name `{name}`, which klams no longer serves — drop it"
        );
    }
    assert_eq!(
        KLAMS_READ_TOOLS,
        [
            "event_search",
            "memory_get",
            "memory_related",
            "memory_search"
        ],
        "widening the klams door is a decision (korg+ GP-17), not an edit"
    );
    assert_eq!(
        KLAMS_WRITE_TOOLS,
        [
            "memory_add",
            "memory_delete",
            "memory_supersede",
            "memory_update"
        ],
        "widening the klams door's writes is a decision (korg+ GP-17), not an edit"
    );
}

#[test]
fn the_klams_catalogue_is_a_full_scope_view() {
    // A read-scope fixture would hide klams's admin tools from the forcing
    // test, and so from any ruling.
    let catalogue = klams_catalogue();
    let admin: Vec<_> = catalogue
        .iter()
        .filter(|n| n.starts_with("memory_admin_"))
        .collect();
    assert!(
        admin.len() >= 6,
        "no admin tools in the fixture: {catalogue:?}"
    );
    for name in admin {
        assert!(KLAMS_REFUSED_TOOLS.contains(&name.as_str()), "{name}");
    }
}

#[tokio::test]
async fn every_refused_klams_tool_is_refused_on_call_and_the_list_is_reads_plus_writes() {
    let h = Harness::start().await;
    let (_, token, _) = h.klams_token().await;

    // Every klams tool outside the eight, plus a korg read and a korg write:
    // the klams door knows only its own lists.
    let refused: Vec<String> = klams_catalogue()
        .into_iter()
        .filter(|n| {
            !KLAMS_READ_TOOLS.contains(&n.as_str()) && !KLAMS_WRITE_TOOLS.contains(&n.as_str())
        })
        .chain(["get_item".to_string(), "add_comment".to_string()])
        .collect();
    assert_eq!(refused.len(), KLAMS_REFUSED_TOOLS.len() + 2);
    for (i, name) in refused.iter().enumerate() {
        let body = h
            .rpc_at(
                "/klams/mcp",
                &token,
                json!({"jsonrpc":"2.0","id":i,"method":"tools/call",
                       "params":{"name":name,"arguments":{}}}),
            )
            .await
            .json_value()
            .await;
        assert_eq!(body["id"], i, "{name}");
        assert_eq!(
            body["error"]["code"], -32602,
            "{name} was not refused: {body}"
        );
        assert!(
            body["error"]["message"]
                .as_str()
                .unwrap()
                .contains("exposes klams's reads and the ruled write set"),
            "{body}"
        );
    }
    assert!(
        h.klams_seen
            .0
            .lock()
            .unwrap()
            .iter()
            .all(|(_, m)| m["method"] != "tools/call"),
        "a refused tools/call reached klams"
    );

    // tools/list, through klams's SSE answer and its priming event.
    let text = h
        .rpc_at(
            "/klams/mcp",
            &token,
            json!({"jsonrpc":"2.0","id":"l","method":"tools/list"}),
        )
        .await
        .text()
        .await
        .unwrap();
    let answer = text
        .split("\n\n")
        .filter_map(|ev| ev.lines().find_map(|l| l.strip_prefix("data: ")))
        .find(|d| !d.trim().is_empty())
        .unwrap_or_else(|| panic!("no answer in {text:?}"));
    let listed: serde_json::Value = serde_json::from_str(answer).unwrap();
    let mut names: Vec<&str> = listed["result"]["tools"]
        .as_array()
        .unwrap()
        .iter()
        .map(|t| t["name"].as_str().unwrap())
        .collect();
    names.sort_unstable();
    let mut expected: Vec<&str> = KLAMS_READ_TOOLS
        .iter()
        .chain(KLAMS_WRITE_TOOLS)
        .copied()
        .collect();
    expected.sort_unstable();
    assert_eq!(names, expected);
    assert_eq!(names.len(), 8);
}

#[tokio::test]
async fn every_klams_write_reaches_klams_with_author_id_stripped() {
    let h = Harness::start().await;
    let (_, token, _) = h.klams_token().await;

    for (i, name) in KLAMS_WRITE_TOOLS.iter().enumerate() {
        let body = h
            .rpc_at(
                "/klams/mcp",
                &token,
                json!({"jsonrpc":"2.0","id":i,"method":"tools/call",
                       "params":{"name":name,"arguments":{
                           "kind":"knowledge","text":"t","id":"m-1",
                           "author_id":FOREIGN_AUTHOR}}}),
            )
            .await
            .text()
            .await
            .unwrap();
        assert!(body.contains(&format!("called {name}")), "{name}: {body}");
    }
    let seen = h.klams_seen.0.lock().unwrap();
    let calls: Vec<_> = seen
        .iter()
        .filter(|(_, m)| m["method"] == "tools/call")
        .collect();
    assert_eq!(calls.len(), KLAMS_WRITE_TOOLS.len());
    for (headers, msg) in calls {
        let name = msg["params"]["name"].as_str().unwrap();
        let arguments = msg["params"]["arguments"].as_object().unwrap();
        // klams fills the author bound to this header: claude-duet.
        assert_eq!(headers["x-homelab-agent"], "claude-duet", "{name}");
        assert!(
            !arguments.contains_key("author_id"),
            "{name} reached klams with an author_id: {msg}"
        );
        // Everything else passes as sent.
        assert_eq!(arguments["kind"], "knowledge", "{name}");
        assert_eq!(arguments["text"], "t", "{name}");
        assert_eq!(arguments["id"], "m-1", "{name}");
    }
    assert!(
        !seen
            .iter()
            .any(|(_, m)| m.to_string().contains(FOREIGN_AUTHOR)),
        "the foreign author_id reached klams"
    );
}

#[tokio::test]
async fn memory_add_is_knowledge_only_and_unstrippable_arguments_are_refused() {
    let h = Harness::start().await;
    let (_, token, _) = h.klams_token().await;

    let refused = [
        (
            "memory_add",
            json!({"kind":"fact","fact_type":"UserFact","payload":{}}),
        ),
        ("memory_add", json!({"kind":"Knowledge","text":"t"})),
        ("memory_add", json!({"kind":null,"text":"t"})),
        ("memory_add", json!({"text":"t"})),
        ("memory_add", json!(null)),
        ("memory_delete", json!("author_id=someone")),
        ("memory_update", json!(["id"])),
    ];
    for (i, (name, arguments)) in refused.iter().enumerate() {
        let body = h
            .rpc_at(
                "/klams/mcp",
                &token,
                json!({"jsonrpc":"2.0","id":i,"method":"tools/call",
                       "params":{"name":name,"arguments":arguments}}),
            )
            .await
            .json_value()
            .await;
        assert_eq!(body["id"], i, "{name} {arguments}");
        assert_eq!(body["error"]["code"], -32602, "{name} {arguments}: {body}");
    }
    let kind_refusal = h
        .rpc_at(
            "/klams/mcp",
            &token,
            json!({"jsonrpc":"2.0","id":"k","method":"tools/call",
                   "params":{"name":"memory_add","arguments":{"kind":"fact"}}}),
        )
        .await
        .json_value()
        .await;
    assert!(
        kind_refusal["error"]["message"]
            .as_str()
            .unwrap()
            .contains("knowledge only"),
        "the refusal must say why: {kind_refusal}"
    );
    assert!(
        h.klams_seen.0.lock().unwrap().is_empty(),
        "a refused klams write reached klams"
    );

    // A delete with no arguments key, or null ones, is forwarded as an
    // object with nothing to strip — klams answers for the missing `id`.
    for (i, params) in [
        json!({"name":"memory_delete"}),
        json!({"name":"memory_delete","arguments":null}),
    ]
    .into_iter()
    .enumerate()
    {
        h.rpc_at(
            "/klams/mcp",
            &token,
            json!({"jsonrpc":"2.0","id":i,"method":"tools/call","params":params}),
        )
        .await;
    }
    let seen = h.klams_seen.0.lock().unwrap();
    assert_eq!(seen.len(), 2);
    for (_, msg) in seen.iter() {
        assert_eq!(msg["params"]["arguments"], json!({}), "{msg}");
    }
}

#[tokio::test]
async fn a_klams_read_keeps_its_author_id_filter() {
    let h = Harness::start().await;
    let (_, token, _) = h.klams_token().await;
    h.rpc_at(
        "/klams/mcp",
        &token,
        json!({"jsonrpc":"2.0","id":1,"method":"tools/call",
               "params":{"name":"event_search","arguments":{"author_id":FOREIGN_AUTHOR}}}),
    )
    .await;
    let seen = h.klams_seen.0.lock().unwrap();
    assert_eq!(
        seen[0].1["params"]["arguments"]["author_id"],
        FOREIGN_AUTHOR
    );
}

#[tokio::test]
async fn a_klams_read_is_refused_at_the_korg_door() {
    let h = Harness::start().await;
    let (_, token, _) = h.access_token().await;
    let body = h
        .rpc(
            &token,
            json!({"jsonrpc":"2.0","id":1,"method":"tools/call",
                   "params":{"name":"memory_search","arguments":{}}}),
        )
        .await
        .json_value()
        .await;
    assert_eq!(body["error"]["code"], -32602);
    assert!(body["error"]["message"]
        .as_str()
        .unwrap()
        .contains("exposes korg's reads and the ruled write set"));
}
